using System;using System.Linq;using System.Collections.Generic;using System.Security.Cryptography;using System.Text;
namespace Synkoz {public sealed partial class MontagePanel {static string SamplingKeyR11(double[] times){if(times==null)return "";using(var h=SHA256.Create())return "-"+BitConverter.ToString(h.ComputeHash(Encoding.UTF8.GetBytes(string.Join(",",times.Select(t=>t.ToString("R",Engine.Inv)))))).Replace("-","").Substring(0,16);}static double[] MeasureSamplesR11(Montage m,string file,double duration){var b=m.Blocks.First(x=>string.Equals(string.IsNullOrEmpty(x.RawFile)?x.File:x.RawFile,file,StringComparison.OrdinalIgnoreCase));double sourceZero=b.Start-(b.RawVideoZero??b.MediaOffset939);double begin=MusicalTimeR11.Beat(m,sourceZero),end=MusicalTimeR11.Beat(m,sourceZero+duration);var times=new List<double>{0};for(double bar=Math.Ceiling(begin/4)*4;bar<end;bar+=4){double t=MusicalTimeR11.Time(m,bar)-sourceZero;if(t>0&&t<duration)times.Add(t);}return times.ToArray();}}}
